import express from 'express';
import fs from 'fs/promises';
import { createStaticPreviewRoutes } from '../routes/library/staticPreview';
import { listenLocally } from './http';

export const startStaticPreviewServer = async (root: string) => {
  const app = express();
  app.use(createStaticPreviewRoutes(await fs.realpath(root)));
  return listenLocally(app);
};
